"""Inspect native CATIA V5 references and position packets without a CAD installation.

This research tool does not yet export STL: component ownership, transform
composition and complete geometry coverage remain unverified. No CAD is uploaded.
Container framing reference: https://github.com/cadmpeg/cadmpeg/blob/main/docs/formats/catia.md
The position and escaped locator productions were investigated on local EFR files.
"""
import argparse
from collections import Counter, defaultdict
import json
import math
from pathlib import Path, PureWindowsPath
import re
import struct


MAGIC = b'V5_CFV2\0'
MAX_INPUT_BYTES = 128 * 1024 * 1024
CATIA_SUFFIXES = {'.catpart', '.catproduct', '.catshape', '.cgr'}
ESCAPED_BYTES = re.compile(rb'(?:\x3b\x01.){10,}', re.DOTALL)


def frame_end(data, offset, marker, limit=None):
    """Accept a length-prefixed frame only inside its enclosing byte extent."""
    limit = len(data) if limit is None else limit
    if offset < 0 or offset + 6 > limit or data[offset:offset + 2] != marker:
        raise ValueError(f'Expected {marker.hex()} frame at {offset}')
    length = struct.unpack_from('<I', data, offset + 2)[0]
    if length < 6 or offset + length > limit:
        raise ValueError(f'Invalid frame length at {offset}')
    return offset + length


def validate_container(data):
    """Reject truncated containers before interpreting any framed records."""
    if len(data) < 64 or data[:8] != MAGIC:
        raise ValueError('Expected a CATIA V5 V5_CFV2 container')
    directory, length = struct.unpack_from('>II', data, 8)
    if directory < 64 or directory + length != len(data) or length < 23:
        raise ValueError('CATIA directory extent does not match the file size')
    if not data[directory:].startswith(b'CATIA_V5 CB0001\0') or not data.endswith(b'CB__END\0'):
        raise ValueError('CATIA directory signature or terminator is invalid')
    return directory


def compact_atom(data, offset, end):
    """Read the compact unsigned atoms used by framed catalog counts."""
    if offset >= end:
        raise ValueError('Truncated compact atom')
    value = data[offset]
    if 0x80 <= value <= 0xd0:
        return value - 0x80, offset + 1
    if 0xd1 <= value <= 0xe4 and offset + 1 < end:
        return (value - 0xd1) * 256 + data[offset + 1] + 1, offset + 2
    raise ValueError('Unsupported compact atom')


def read_catalog(data, offset, limit):
    """Decode a complete catalog; its names alone do not establish instances."""
    end = frame_end(data, offset, b'\x7c\x02', limit)
    count, cursor = compact_atom(data, offset + 6, end)
    entries = []
    for _ in range(count - 1):
        if cursor >= end:
            raise ValueError('Truncated catalog entry')
        length = data[cursor]
        header = 1
        if length == 0:
            if cursor + 5 > end:
                raise ValueError('Truncated wide catalog entry')
            length = struct.unpack_from('<I', data, cursor + 1)[0] + 5
            header = 5
        if length < header or cursor + length > end:
            raise ValueError('Catalog entry crosses its frame')
        entries.append(data[cursor + header:cursor + length].decode('utf-8'))
        cursor += length
    if cursor != end:
        raise ValueError('Catalog has trailing bytes')
    return entries, end


def schema_symbol(data, offset, end, catalog):
    """Resolve the short symbol or explicit ordinal form seen in these files."""
    if offset >= end:
        raise ValueError('Missing schema selector')
    value = data[offset]
    if value == 0x32 and offset + 5 <= end:
        ordinal = struct.unpack_from('<I', data, offset + 1)[0]
        offset += 5
    elif 0x34 <= value < 0x80:
        ordinal = value - 0x34
        offset += 1
    else:
        raise ValueError('Unsupported schema selector encoding')
    if ordinal >= len(catalog):
        raise ValueError('Schema selector outside catalog')
    return catalog[ordinal], offset


def locator_references(data, limit):
    """Decode counted, individually escaped octets containing DocId/File locators."""
    references = []
    for match in ESCAPED_BYTES.finditer(data, 64, limit):
        start = match.start()
        if start < 5 or data[start - 5] != 0x22:
            continue
        declared = struct.unpack_from('<I', data, start - 4)[0]
        if declared != len(match.group()) // 3:
            continue
        payload = match.group()[2::3]
        cursor = payload.find(b'\x05DocId')
        if cursor < 0 or len(payload) < cursor + 12:
            continue
        cursor += 8
        if payload[cursor:cursor + 6] != b'\x01\x04File':
            continue
        cursor += 6
        if cursor >= len(payload):
            continue
        kind_length = payload[cursor]
        cursor += 1
        kind = payload[cursor:cursor + kind_length].decode('ascii', errors='replace')
        cursor += kind_length
        if cursor + 2 > len(payload):
            continue
        path_length = struct.unpack_from('<H', payload, cursor)[0]
        cursor += 2
        if cursor + path_length != len(payload):
            continue
        path = payload[cursor:].decode('cp1252')
        if PureWindowsPath(path).suffix.lower() not in CATIA_SUFFIXES:
            continue
        identity = payload[2:18].hex() if payload.startswith(b'\x11\x03') else None
        references.append({'offset': start, 'kind': kind, 'saved_path': path,
                           'document_identity': identity, 'payload_hex': payload.hex()})
    return references


def graph_tables(data, limit):
    """Require a complete entity table, object graph, value block and catalog chain."""
    cursor = 64
    while True:
        start = data.find(b'\x7c\x04', cursor, limit)
        if start < 0:
            return
        cursor = start + 2
        try:
            graph_start = frame_end(data, start, b'\x7c\x04', limit)
            graph_end = frame_end(data, graph_start, b'\x7c\x08', limit)
            values_end = frame_end(data, graph_end, b'\x7c\x0b', limit)
            # The value block's final FE sits outside its declared length.
            if values_end >= limit or data[values_end] != 0xfe:
                continue
            catalog, catalog_end = read_catalog(data, values_end + 1, limit)
            entities = []
            item = start + 6
            while item < graph_start - 1:
                end = frame_end(data, item, b'\x7c\x05', graph_start - 1)
                entities.append((item, end))
                item = end
            if item != graph_start - 1 or data[item] != 0xde:
                continue
            graphs = []
            item = graph_start + 6
            while item < graph_end:
                end = frame_end(data, item, b'\x7c\x09', graph_end)
                graphs.append((item, end))
                item = end
            if len(entities) != len(graphs):
                continue
        except (ValueError, UnicodeDecodeError):
            continue
        yield graph_start, catalog, list(zip(entities, graphs))
        cursor = catalog_end


def matrix_metrics(values):
    """Check both orthogonality and determinant without assuming a matrix layout."""
    rows = [values[i:i + 3] for i in range(0, 9, 3)]
    residual = max(abs(sum(rows[i][k] * rows[j][k] for k in range(3)) - (i == j))
                   for i in range(3) for j in range(3))
    a, b, c = rows
    determinant = (a[0] * (b[1] * c[2] - b[2] * c[1])
                   - a[1] * (b[0] * c[2] - b[2] * c[0])
                   + a[2] * (b[0] * c[1] - b[1] * c[0]))
    return residual, determinant


def position_packet(payload, catalog):
    """Decode the observed 12-scalar position production, retaining uncertain semantics."""
    name, cursor = schema_symbol(payload, 0, len(payload), catalog)
    if name != '_Position':
        raise ValueError('Not a supported position packet')
    flags, cursor = compact_atom(payload, cursor, len(payload))
    signature = payload[cursor:cursor + 6]
    if signature not in (b'\xe8\xf4\x07\x37\x8d\x81', b'\xe8\xe0\x07\x37\x8d\x81'):
        raise ValueError('Not a supported position packet')
    cursor += 6
    values = []
    opcodes = []
    for _ in range(12):
        if cursor >= len(payload):
            raise ValueError('Truncated position scalars')
        opcode = payload[cursor]
        opcodes.append(opcode)
        cursor += 1
        if opcode == 0xe6:
            if cursor + 8 > len(payload):
                raise ValueError('Truncated binary64 position scalar')
            value = struct.unpack_from('<d', payload, cursor)[0]
            cursor += 8
        elif opcode in (0xe7, 0xe8, 0xe9):
            # This interpretation is tested by rotation invariants, not a vendor export.
            value = {0xe7: 1.0, 0xe8: 0.0, 0xe9: -1.0}[opcode]
        else:
            raise ValueError(f'Unsupported position scalar opcode {opcode:02x}')
        if not math.isfinite(value):
            raise ValueError('Non-finite position scalar')
        values.append(value)
    if cursor >= len(payload) or payload[cursor] != 0xfe:
        raise ValueError('Position packet has no immediate terminator')
    residual, determinant = matrix_metrics(values)
    return {'scalars': values, 'scalar_opcodes': opcodes, 'prefix_atom': flags,
            'type_signature': signature.hex(),
            'orthogonality_error': residual, 'determinant': determinant,
            'proper_rotation_candidate': residual < 1e-6 and abs(determinant - 1) < 1e-6,
            'placement_verified': False, 'matrix_layout': 'unverified',
            'scalar_interpretation': 'experimental E6=binary64, E7=1, E8=0, E9=-1'}


def inspect_graphs(data, limit):
    """Associate position packets with physical entity frames, never guessed instances."""
    positions = []
    summaries = []
    for graph_offset, catalog, pairs in graph_tables(data, limit):
        summary = {'offset': graph_offset, 'entities': len(pairs), 'positions': 0,
                   'unsupported_position_packets': 0, 'classes': Counter()}
        for (start, end), (object_start, object_end) in pairs:
            try:
                definition = start + 7
                value_start = frame_end(data, definition, b'\x7c\x06', end)
                value_end = frame_end(data, value_start, b'\x7c\x07', end)
                prefix = data[definition + 6:value_start]
                class_name, name_cursor = schema_symbol(prefix, 2, len(prefix), catalog)
                object_name, _ = schema_symbol(prefix, name_cursor, len(prefix), catalog)
            except ValueError:
                continue
            summary['classes'][class_name] += 1
            payload = data[value_start + 6:value_end]
            try:
                field, _ = schema_symbol(payload, 0, len(payload), catalog)
            except ValueError:
                continue
            if field != '_Position':
                continue
            try:
                position = position_packet(payload, catalog)
            except ValueError:
                summary['unsupported_position_packets'] += 1
                continue
            position.update({'graph_offset': graph_offset, 'entity_offset': start,
                             'value_offset': value_start + 6, 'class': class_name,
                             'name': object_name, 'payload_hex': payload.hex(),
                             'object_record_hex': data[object_start:object_end].hex()})
            head = object_start + 8
            if data[head:head + 1] == b'\xe5' and head + 5 <= object_end:
                length = struct.unpack_from('<I', data, head + 1)[0]
                if length >= 18 and head + 5 + length <= object_end and data[head + 5:head + 7] == b'\x11\x03':
                    position['external_document_identity'] = data[head + 7:head + 23].hex()
            positions.append(position)
            summary['positions'] += 1
        summaries.append(summary)
    return summaries, positions


def resolve_reference(saved_path, source, root, index):
    """Prefer exact directory suffixes; never silently pick an ambiguous basename."""
    parts = PureWindowsPath(saved_path).parts
    candidates = index.get(parts[-1].casefold(), [])
    if not candidates:
        return {'status': 'missing', 'candidates': []}
    scores = []
    for path in candidates:
        score = 0
        for left, right in zip(reversed(parts), reversed(path.relative_to(root).parts)):
            if left.casefold() != right.casefold():
                break
            score += 1
        scores.append((score, path))
    best = max(score for score, _ in scores)
    winners = [path for score, path in scores if score == best]
    result = {'status': 'candidate' if len(winners) == 1 else 'ambiguous',
              'matching_suffix_segments': best, 'candidates': [str(p) for p in winners],
              'identity_verified': False}
    if len(winners) == 1 and winners[0] == source:
        result['status'] = 'self'
    return result


def inspect_file(source, root, index):
    """Emit byte-backed findings and explicit export blockers for one native document."""
    if source.stat().st_size > MAX_INPUT_BYTES:
        raise ValueError(f'Input exceeds {MAX_INPUT_BYTES} bytes')
    data = source.read_bytes()
    limit = validate_container(data)
    references = locator_references(data, limit)
    for reference in references:
        reference['resolution'] = resolve_reference(reference['saved_path'], source, root, index)
    graphs, positions = inspect_graphs(data, limit)
    for position in positions:
        identity = position.get('external_document_identity')
        position['document_reference_offsets'] = [r['offset'] for r in references
                                                  if identity and r['document_identity'] == identity]
    return {'source': str(source), 'bytes': len(data), 'directory_offset': limit,
            'references': references, 'graphs': graphs, 'position_candidates': positions,
            'stl_export_ready': False,
            'blockers': ['Occurrence ownership and hierarchy are not decoded.',
                         'Matrix layout, coordinate frame and composition are unverified.',
                         'Complete referenced-part geometry has not been decoded.']}


def main():
    """Write a local research report, without overwriting input or pretending to export STL."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('source', type=Path)
    parser.add_argument('output', type=Path, help='New JSON report path (not an STL)')
    parser.add_argument('--root', type=Path, help='Folder containing the assembly and parts')
    parser.add_argument('--recursive', action='store_true', help='Inspect uniquely matched product dependencies, not assembly occurrences')
    args = parser.parse_args()
    source = args.source.resolve()
    root = (args.root or source.parent).resolve()
    output = args.output.resolve()
    if not source.is_file() or not source.is_relative_to(root):
        parser.error('Source must be a file inside --root')
    if output.exists() or output.suffix.lower() != '.json':
        parser.error('Output must be a new .json file')
    index = defaultdict(list)
    for path in root.rglob('*'):
        if path.suffix.lower() in CATIA_SUFFIXES and path.is_file():
            resolved = path.resolve()
            if resolved.is_relative_to(root):
                index[path.name.casefold()].append(resolved)
    try:
        report = inspect_file(source, root, index)
        if args.recursive:
            documents = [report]
            visited = {source}
            for document in documents:
                for reference in document.get('references', []):
                    resolution = reference['resolution']
                    if resolution['status'] != 'candidate':
                        continue
                    child = Path(resolution['candidates'][0])
                    if child.suffix.lower() != '.catproduct' or child in visited:
                        continue
                    visited.add(child)
                    try:
                        documents.append(inspect_file(child, root, index))
                    except (ValueError, OSError) as error:
                        documents.append({'source': str(child), 'error': str(error),
                                          'stl_export_ready': False})
                    if len(visited) > 10000:
                        raise ValueError('Product dependency limit exceeded')
            report = {'source': str(source), 'documents': documents, 'stl_export_ready': False,
                      'note': 'Dependency traversal is not an assembly occurrence tree.'}
    except (ValueError, OSError) as error:
        parser.exit(1, f'Cannot decode: {error}\n')
    output.parent.mkdir(parents=True, exist_ok=True)
    with output.open('x', encoding='utf-8') as stream:
        json.dump(report, stream, indent=2)
    documents = report.get('documents', [report])
    references = sum(len(d.get('references', [])) for d in documents)
    positions = sum(len(d.get('position_candidates', [])) for d in documents)
    print(f'Recovered {references} document locators and {positions} position candidates '
          f'from {len(documents)} documents; STL export remains blocked.')
    print(output)


if __name__ == '__main__':
    main()
